export function Inspector({
  title = "{{title}}",
  position = "{{position}}",
  width = {{width}},
  accent = "{{accent}}",
}) {
  const isLeft = position === "left";
  const rows = [["X", "128"], ["Y", "64"], ["Width", "240"], ["Height", "96"]];
  return (
    <div style={{ display: "flex", flexDirection: isLeft ? "row-reverse" : "row", height: 160, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430", border: "1px solid #24143022" }}>
      <div style={{ flex: 1, display: "flex", alignItems: "center", justifyContent: "center", color: "#24143066", backgroundImage: "repeating-linear-gradient(45deg, #24143008 0 8px, transparent 8px 16px)" }}>Canvas</div>
      <aside style={{ flex: "none", boxSizing: "border-box", width, background: "#FAF7F2", padding: 12, overflowY: "auto", borderLeft: isLeft ? "none" : `1px solid ${accent}`, borderRight: isLeft ? `1px solid ${accent}` : "none" }}>
        <h4 style={{ margin: "0 0 10px", fontSize: 13, color: accent }}>{title}</h4>
        {rows.map(([k, v]) => (
          <div key={k} style={{ display: "flex", justifyContent: "space-between", padding: "5px 0", borderBottom: "1px solid #24143014" }}>
            <span style={{ color: "#24143099" }}>{k}</span><span>{v}</span>
          </div>
        ))}
      </aside>
    </div>
  );
}
